-- Two-stage Connection generation uses a reviewed database template library,
-- while each Journal entry type gets one durable daily slot.

create table if not exists public.connection_scenario_families (
  family_key text primary key,
  name text not null,
  section text not null check (section in ('missed','world','ways_in','between')),
  module_key text,
  routing_hint text not null,
  sort_order integer not null,
  library_version text not null default 'v2',
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.connection_scenario_templates (
  template_id text primary key,
  family_key text not null references public.connection_scenario_families(family_key) on update cascade,
  section text not null check (section in ('missed','world','ways_in','between')),
  module_key text,
  scenario_key text not null unique,
  scenario text not null,
  required_evidence text not null,
  disqualifiers text not null,
  emotional_weight text,
  tone_mode text,
  depth_level text,
  field_pattern text not null,
  label_options text,
  template_card jsonb not null,
  blocked_overlap text,
  review_status text not null default 'approved' check (review_status in ('approved','disabled')),
  library_version text not null default 'v2',
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (jsonb_typeof(template_card) = 'object')
);
create index if not exists connection_scenario_templates_family
  on public.connection_scenario_templates(family_key, active, template_id);

alter table public.connection_scenario_families enable row level security;
alter table public.connection_scenario_templates enable row level security;
drop policy if exists connection_scenario_families_service on public.connection_scenario_families;
create policy connection_scenario_families_service on public.connection_scenario_families
  for all to service_role using (true) with check (true);
drop policy if exists connection_scenario_templates_service on public.connection_scenario_templates;
create policy connection_scenario_templates_service on public.connection_scenario_templates
  for all to service_role using (true) with check (true);

insert into public.connection_scenario_families(family_key,name,section,module_key,routing_hint,sort_order,library_version,active)
select family_key,name,section,module_key,routing_hint,sort_order,library_version,true
from jsonb_to_recordset($families$
[{"family_key":"upcoming_moment","name":"Upcoming moment","section":"missed","module_key":"worth_knowing","routing_hint":"A confirmed future moment whose preparation, stakes, anticipation, or consequence makes it important.","sort_order":1,"library_version":"v2"},{"family_key":"first","name":"First","section":"missed","module_key":"worth_knowing","routing_hint":"A genuine first experience, responsibility, attempt, or step into unfamiliar territory.","sort_order":2,"library_version":"v2"},{"family_key":"material_change","name":"Material change","section":"missed","module_key":"worth_knowing","routing_hint":"A concrete change in work, home, health routine, responsibility, access, or daily circumstances.","sort_order":3,"library_version":"v2"},{"family_key":"milestone_or_quiet_win","name":"Milestone or quiet win","section":"missed","module_key":"worth_knowing","routing_hint":"A completed effort, breakthrough, recovery step, personal milestone, or understated success.","sort_order":4,"library_version":"v2"},{"family_key":"mood_and_energy","name":"Mood and energy","section":"world","module_key":"recent_vibe","routing_hint":"A current emotional or energy pattern supported by continuity, repetition, or a clearly ongoing state.","sort_order":5,"library_version":"v2"},{"family_key":"routine_and_pace","name":"Routine and pace","section":"world","module_key":"recent_vibe","routing_hint":"A repeated routine, tempo, schedule pattern, or way of structuring and recovering from the day.","sort_order":6,"library_version":"v2"},{"family_key":"developing_interest","name":"Developing interest","section":"world","module_key":"what_theyre_into","routing_hint":"A repeated or explicitly developing curiosity, hobby, subject, practice, or source of attention.","sort_order":7,"library_version":"v2"},{"family_key":"priority_and_outlook","name":"Priority and outlook","section":"world","module_key":"recent_vibe","routing_hint":"A supported shift or continuity in what matters, what they protect, or how they approach the near future.","sort_order":8,"library_version":"v2"},{"family_key":"listening_and_venting","name":"Listening and venting","section":"ways_in","module_key":null,"routing_hint":"They need room to express or decompress without advice, fixing, interrogation, or redirection.","sort_order":9,"library_version":"v2"},{"family_key":"comfort_and_reassurance","name":"Comfort and reassurance","section":"ways_in","module_key":null,"routing_hint":"They need warmth, validation, steadiness, or reassurance after strain, uncertainty, or hurt.","sort_order":10,"library_version":"v2"},{"family_key":"space_and_boundaries","name":"Space and boundaries","section":"ways_in","module_key":null,"routing_hint":"They need reduced demands, privacy, time, or a boundary respected without withdrawal or punishment.","sort_order":11,"library_version":"v2"},{"family_key":"encouragement","name":"Encouragement","section":"ways_in","module_key":null,"routing_hint":"They need confidence, recognition, momentum, or a gentle push around something they care about.","sort_order":12,"library_version":"v2"},{"family_key":"practical_help","name":"Practical help","section":"ways_in","module_key":null,"routing_hint":"A concrete burden can be reduced by a specific offer, task, reminder, or piece of logistical help.","sort_order":13,"library_version":"v2"},{"family_key":"companionship","name":"Companionship","section":"ways_in","module_key":null,"routing_hint":"Easy presence, shared lightness, or low-pressure company would fit better than analysis or fixing.","sort_order":14,"library_version":"v2"},{"family_key":"conversation_opening","name":"Conversation opening","section":"ways_in","module_key":null,"routing_hint":"A useful conversation can be opened through a specific angle not already obvious from the memory.","sort_order":15,"library_version":"v2"},{"family_key":"join_and_follow_up","name":"Join and follow up","section":"ways_in","module_key":null,"routing_hint":"The evidence supports joining an activity, following up at the right time, or sharing something relevant.","sort_order":16,"library_version":"v2"},{"family_key":"parallel_routines","name":"Parallel routines","section":"between","module_key":"shared_rhythm","routing_hint":"Both people's recent evidence shows a similar repeated activity, pace, habit, or timing.","sort_order":17,"library_version":"v2"},{"family_key":"shared_phase","name":"Shared phase","section":"between","module_key":"shared_rhythm","routing_hint":"Both are independently moving through a similar emotional, practical, or transitional phase.","sort_order":18,"library_version":"v2"},{"family_key":"aligned_priorities","name":"Aligned priorities","section":"between","module_key":"shared_rhythm","routing_hint":"Both independently signal the same value, goal, concern, or protected priority.","sort_order":19,"library_version":"v2"},{"family_key":"complementary_rhythm","name":"Complementary rhythm","section":"between","module_key":"shared_rhythm","routing_hint":"Their different recent patterns fit together in a useful, affectionate, or revealing way.","sort_order":20,"library_version":"v2"},{"family_key":"interaction_pattern","name":"Interaction pattern","section":"between","module_key":"shared_rhythm","routing_hint":"Recent evidence from both sides supports a recurring way they reach, respond, or make room for each other.","sort_order":21,"library_version":"v2"}]
$families$::jsonb) as x(family_key text,name text,section text,module_key text,routing_hint text,sort_order integer,library_version text)
on conflict (family_key) do update set name=excluded.name,section=excluded.section,module_key=excluded.module_key,routing_hint=excluded.routing_hint,sort_order=excluded.sort_order,library_version=excluded.library_version,active=true,updated_at=now();

insert into public.connection_scenario_templates(template_id,family_key,section,module_key,scenario_key,scenario,required_evidence,disqualifiers,emotional_weight,tone_mode,depth_level,field_pattern,label_options,template_card,blocked_overlap,review_status,library_version,active)
select template_id,family_key,section,module_key,scenario_key,scenario,required_evidence,disqualifiers,emotional_weight,tone_mode,depth_level,field_pattern,label_options,template_card,blocked_overlap,'approved',library_version,true
from jsonb_to_recordset($templates$
[{"template_id":"M-001","family_key":"upcoming_moment","section":"missed","module_key":"worth_knowing","scenario_key":"upcoming_high_stakes_presentation","scenario":"An unusually important presentation is approaching after sustained preparation.","required_evidence":"A future presentation plus explicit importance, nerves, or several days of preparation.","disqualifiers":"Routine meeting; no indication it matters; event already passed without a meaningful update.","emotional_weight":"ordinary","tone_mode":"warm_clear","depth_level":"L3 Insight","field_pattern":"L2 frame plus one evidence-supported significance line. No action.","label_options":"BIG WEEK, COMING UP","template_card":{"label":"BIG WEEK","title":"A Lot Rides on This One","observation":"They have an important presentation coming up after several days of focused preparation. It carries more weight for them than a routine work task.","meaning":"This is a concrete change in their week, not just a passing detail.","takeaway":null},"blocked_overlap":"Do not reuse the same event in Their World Lately or Ways In unless a separate support need is independently stated.","library_version":"v2"},{"template_id":"M-002","family_key":"upcoming_moment","section":"missed","module_key":"worth_knowing","scenario_key":"upcoming_exam_or_certification","scenario":"A meaningful exam or certification attempt is close.","required_evidence":"A future exam plus stated preparation, consequence, or personal importance.","disqualifiers":"Ordinary homework; vague mention of studying; exact scores or identifiable institution details.","emotional_weight":"ordinary","tone_mode":"warm_clear","depth_level":"L2 Framed","field_pattern":"Label, title, and observation only. No action.","label_options":"TEST AHEAD, BIG WEEK","template_card":{"label":"TEST AHEAD","title":"The Prep Is About to Count","observation":"They have a significant exam next week and have been preparing consistently. This attempt matters to them beyond simply finishing ano