ine.","meaning":null,"takeaway":null},"blocked_overlap":"Do not reuse the same event in Their World Lately or Ways In unless a separate support need is independently stated.","library_version":"v2"},{"template_id":"M-007","family_key":"upcoming_moment","section":"missed","module_key":"worth_knowing","scenario_key":"upcoming_reunion_or_visit","scenario":"A long-awaited reunion or visit is confirmed.","required_evidence":"A confirmed visit plus evidence of anticipation or long separation.","disqualifiers":"Exact flight, hotel, address, or itinerary; casual unconfirmed idea.","emotional_weight":"ordinary","tone_mode":"warm_clear","depth_level":"L2 Framed","field_pattern":"Label, title, and observation only. No action.","label_options":"LONG AWAITED, COMING UP","template_card":{"label":"LONG AWAITED","title":"A Reunion Is Finally Close","observation":"They are about to see someone important after a long stretch apart. The visit has been carrying real anticipation for them.","meaning":null,"takeaway":null},"blocked_overlap":"Do not reuse the same event in Their World Lately or Ways In unless a separate support need is independently stated.","library_version":"v2"},{"template_id":"M-008","family_key":"upcoming_moment","section":"missed","module_key":"worth_knowing","scenario_key":"upcoming_hosting_responsibility","scenario":"They are hosting or leading an event that matters to them.","required_evidence":"A specific upcoming hosting role plus preparation or emotional investment.","disqualifiers":"Ordinary social plan; no responsibility; identifiable guest list or location.","emotional_weight":"ordinary","tone_mode":"warm_clear","depth_level":"L2 Framed","field_pattern":"Label, title, and observation only. No action.","label_options":"HOST MODE, BIG WEEK","template_card":{"label":"HOST MODE","title":"They’re Holding the Whole Thing","observation":"They are taking the lead on an upcoming gathering and have put real care into making it work. It is more responsibility than sim