on conflict (template_id) do update set family_key=excluded.family_key,section=excluded.section,module_key=excluded.module_key,scenario_key=excluded.scenario_key,scenario=excluded.scenario,required_evidence=excluded.required_evidence,disqualifiers=excluded.disqualifiers,emotional_weight=excluded.emotional_weight,tone_mode=excluded.tone_mode,depth_level=excluded.depth_level,field_pattern=excluded.field_pattern,label_options=excluded.label_options,template_card=excluded.template_card,blocked_overlap=excluded.blocked_overlap,review_status='approved',library_version=excluded.library_version,active=true,updated_at=now();


alter table public.reflect_drafts
  add column if not exists journal_kind text;
alter table public.reflects
  add column if not exists journal_kind text;

update public.reflect_drafts set journal_kind = case
  when friend_user_id is not null then 'remember_together'
  when mode = 'prompt' then 'tap_your_day'
  else 'write_freely'
end where journal_kind is null;
update public.reflects r set journal_kind = coalesce(
  (select d.journal_kind from public.reflect_drafts d
    where d.saved_reflect_id = r.id or d.finalized_reflect_id = r.id
    order by d.created_at desc limit 1),
  case when r.mode = 'prompt' then 'tap_your_day' else 'write_freely' end
) where journal_kind is null;

alter table public.reflect_drafts alter column journal_kind set default 'write_freely';
alter table public.reflect_drafts alter column journal_kind set not null;
alter table public.reflects alter column journal_kind set default 'write_freely';
alter table public.reflects alter column journal_kind set not null;
alter table public.reflect_drafts drop constraint if exists reflect_drafts_journal_kind_check;
alter table public.reflect_drafts add constraint reflect_drafts_journal_kind_check
  check (journal_kind in ('write_freely','tap_your_day','remember_together'));
alter table public.reflects drop constraint if exists reflects_journal_kind_check;
alter table public.reflects add constraint reflects_journal_kind_check
  check (journal_kind in ('write_freely','tap_your_day','remember_together'));

create table if not exists public.daily_journal_slots (
  user_id uuid not null references public.profiles(id) on delete cascade,
  local_date date not null,
  journal_kind text not null check (journal_kind in ('write_freely','tap_your_day','remember_together')),
  status text not null default 'in_progress' check (status in ('in_progress','completed')),
  draft_id uuid references public.reflect_drafts(id) on delete set null,
  reflect_id uuid references public.reflects(id) on delete cascade,
  created_at timestamptz not null default now(),
  completed_at timestamptz,
  primary key (user_id, local_date, journal_kind),
  unique (draft_id),
  unique (reflect_id)
);
create index if not exists daily_journal_slots_user_date
  on public.daily_journal_slots(user_id, local_date);
alter table public.daily_journal_slots enable row level security;
drop policy if exists daily_journal_slots_service on public.daily_journal_slots;
create policy daily_journal_slots_service on public.daily_journal_slots
  for all to service_role using (true) with check (true);

insert into public.daily_journal_slots(user_id,local_date,journal_kind,status,reflect_id,completed_at,created_at)
select user_id, local_date, journal_kind, 'completed', id, created_at, created_at
from (
  select r.*, row_number() over (
    partition by user_id, local_date, journal_kind order by created_at, id
  ) as slot_rank
  from public.reflects r
) ranked
where slot_rank = 1
on conflict (user_id,local_date,journal_kind) do nothing;

create or replace function public.complete_daily_journal_slot()
returns trigger language plpgsql security definer set search_path=public as $$
begin
  if new.finalized_reflect_id is not null and old.finalized_reflect_id is null then
    update public.daily_journal_slots set status='completed', completed_at=coalesce(completed_at,now())
    where draft_id=new.id or reflect_id=new.finalized_reflect_id;
  end if;
  return new;
end $$;
drop trigger if exists complete_daily_journal_slot_after_settlement on public.reflect_drafts;
create trigger complete_daily_journal_slot_after_settlement
after update of finalized_reflect_id on public.reflect_drafts
for each row execute function public.complete_daily_journal_slot();

create or replace function public.begin_saved_reflect(p_user_id uuid, p_payload jsonb, p_memories jsonb, p_xp integer, p_week text)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  d public.reflect_drafts%rowtype;
  receipt jsonb;
  staged jsonb;
  v_kind text;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text, 0));
  select * into d from public.reflect_drafts
    where user_id = p_user_id and idempotency_key = p_payload->>'idempotency_key' for update;
  if found and (d.saved_reflect_id is not null or d.finalized_reflect_id is not null) then
    return jsonb_build_object('draft', to_jsonb(d));
  end if;
  if (p_payload->>'local_date')::date not between (now() at time zone 'UTC')::date - 1
      and (now() at time zone 'UTC')::date + 1 then
    return jsonb_build_object('error', 'invalid_local_date');
  end if;
  v_kind := case
    when p_payload->>'journal_kind' in ('write_freely','tap_your_day','remember_together')
      then p_payload->>'journal_kind'
    when nullif(p_payload->>'friend_user_id','') is not null then 'remember_together'
    when p_payload->>'mode' = 'prompt' then 'tap_your_day'
    else 'write_freely'
  end;
  if exists(select 1 from public.daily_journal_slots
    where user_id=p_user_id and local_date=(p_payload->>'local_date')::date and journal_kind=v_kind) then
    return jsonb_build_object('error','journal_kind_used','journal_kind',v_kind);
  end if;
  if d.id is null then
    insert into public.reflect_drafts(user_id,idempotency_key,prompt_id,body,local_date,mode,source_kit,friend_user_id,matches,journal_kind)
    values(p_user_id,p_payload->>'idempotency_key',(p_payload->>'prompt_id')::smallint,
      p_payload->>'body',(p_payload->>'local_date')::date,p_payload->>'mode',
      p_payload->>'source_kit',(p_payload->>'friend_user_id')::uuid,p_payload->'matches',v_kind)
    returning * into d;
  else
    update public.reflect_drafts set journal_kind=v_kind where id=d.id returning * into d;
  end if;
  if d.friend_user_id is not null and not exists(
    select 1 from public.pairings where user_id=p_user_id and partner_user_id=d.friend_user_id
  ) then return jsonb_build_object('error','pairing_required'); end if;
  update public.reflect_drafts set friend_user_id=null where id=d.id;
  receipt := public.finalize_reflect_draft(p_user_id,d.id,'[]','[]',p_xp,p_week);
  update public.reflect_drafts set friend_user_id=d.friend_user_id where id=d.id;
  if receipt->>'error' is not null then return receipt; end if;
  -- Reservation is private until the settlement screen is completed. Preserve
  -- the durable workflow's original privacy boundary while adding the kind.
  update public.reflects set
    journal_kind=v_kind, shared_to_friends=false, shared_with_user_id=null
  where id=(receipt->>'reflect_id')::uuid;
  insert into public.daily_journal_slots(user_id,local_date,journal_kind,status,draft_id,reflect_id)
  values(p_user_id,(p_payload->>'local_date')::date,v_kind,'in_progress',d.id,(receipt->>'reflect_id')::uuid);
  select coalesce(jsonb_agg(jsonb_build_object(
    'itemId',m->>'itemId','text',coalesce(p_memories->>(m->>'itemId'),''),
    'source','ai','visible',true,'edited',false
  )),'[]') into staged from jsonb_array_elements(d.matches) m;
  update public.reflect_drafts set
    saved_reflect_id=(receipt->>'reflect_id')::uuid,finalized_reflect_id=null,
    save_receipt=receipt,settlement_memories=staged
    where id=d.id returning * into d;
  perform public.edit_reflect_item_memories(p_user_id,d.saved_reflect_id,
    (select coalesce(jsonb_agg(e || '{"visible":false}'::jsonb),'[]') from jsonb_array_elements(staged) e));
  return jsonb_build_object('draft',to_jsonb(d));
end $$;
revoke all on function public.begin_saved_reflect(uuid,jsonb,jsonb,integer,text) from public,anon,authenticated;
grant execute on function public.begin_saved_reflect(uuid,jsonb,jsonb,integer,text) to service_role;

create or replace function public.submit_reflect_with_kind(
  p_user_id uuid,p_prompt_id smallint,p_body text,p_local_date date,p_iso_week text,
  p_xp_amount int,p_dimension_hits jsonb,p_source_kit kit_t default null,
  p_shared_to_friends boolean default true,p_mode text default 'typing',p_journal_kind text default null
) returns jsonb language plpgsql security definer set search_path=public as $$
declare receipt jsonb; v_kind text;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_user_id::text,0));
  v_kind := case
    when p_journal_kind in ('write_freely','tap_your_day','remember_together') then p_journal_kind
    when p_mode='prompt' then 'tap_your_day' else 'write_freely' end;
  if exists(select 1 from public.daily_journal_slots
    where user_id=p_user_id and local_date=p_local_date and journal_kind=v_kind) then
    return jsonb_build_object('error','journal_kind_used','journal_kind',v_kind);
  end if;
  receipt := public.submit_reflect(p_user_id,p_prompt_id,p_body,p_local_date,p_iso_week,
    p_xp_amount,p_dimension_hits,p_source_kit,p_shared_to_friends,p_mode);
  if receipt->>'error' is not null then return receipt; end if;
  update public.reflects set journal_kind=v_kind where id=(receipt->>'reflect_id')::uuid;
  insert into public.daily_journal_slots(user_id,local_date,journal_kind,status,reflect_id,completed_at)
  values(p_user_id,p_local_date,v_kind,'completed',(receipt->>'reflect_id')::uuid,now());
  return receipt;
end $$;
revoke all on function public.submit_reflect_with_kind(uuid,smallint,text,date,text,int,jsonb,kit_t,boolean,text,text)
  from public,anon,authenticated;
grant execute on function public.submit_reflect_with_kind(uuid,smallint,text,date,text,int,jsonb,kit_t,boolean,text,text)
  to service_role;

create table if not exists public.connection_analysis_jobs (
  reflect_id uuid primary key references public.reflects(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  local_date date not null,
  journal_kind text not null check (journal_kind in ('write_freely','tap_your_day','remember_together')),
  status text not null default 'pending'
    check (status in ('pending','processing','completed','no_update','skipped','failed')),
  attempts integer not null default 0,
  stage_one_result jsonb,
  stage_one_usage jsonb,
  error text,
  next_attempt_at timestamptz not null default now(),
  claimed_at timestamptz,
  processed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists connection_analysis_jobs_claimable
  on public.connection_analysis_jobs(next_attempt_at,created_at)
  where status in ('pending','failed');
alter table public.connection_analysis_jobs enable row level security;
drop policy if exists connection_analysis_jobs_service on public.connection_analysis_jobs;
create policy connection_analysis_jobs_service on public.connection_analysis_jobs
  for all to service_role using (true) with check (true);

alter table public.reflect_ai_analyses
  add column if not exists connection_stage_one jsonb,
  add column if not exists connection_signal_results jsonb,
  add column if not exists connection_writer_version text,
  add column if not exists template_library_version text;

create or replace function public.claim_connection_analysis_job(p_reflect_id uuid default null)
returns setof public.connection_analysis_jobs language sql security definer set search_path=public as $$
  update public.connection_analysis_jobs j set
    status='processing',attempts=j.attempts+1,claimed_at=now(),updated_at=now(),error=null
  where j.reflect_id in (
    select reflect_id from public.connection_analysis_jobs
    where (p_reflect_id is null or reflect_id=p_reflect_id)
      and attempts < 3
      and next_attempt_at <= now()
      and (status in ('pending','failed') or (status='processing' and claimed_at < now()-interval '3 minutes'))
    order by created_at
    limit case when p_reflect_id is null then 8 else 1 end
    for update skip locked
  )
  returning j.*;
$$;
revoke all on function public.claim_connection_analysis_job(uuid) from public,anon,authenticated;
grant execute on function public.claim_connection_analysis_job(uuid) to service_role;
